#!/usr/bin/env bash
set -Eeuo pipefail
[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] Run with sudo/root"; exit 1; }

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
DOMAIN="$(python3 - <<'PY'
import json
try:
 d=json.load(open('/etc/hyper-cs16/runtime.json',encoding='utf-8')); print(d.get('domain') or 'www.avito.hyper-host.pw')
except Exception: print('www.avito.hyper-host.pw')
PY
)"
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-sql-admin-manager-v1-${STAMP}"
mkdir -p "$BACKUP"

for f in "$SRC_CTL" "$SRC_UI" "$LIVE_CTL" "$LIVE_UI"; do
 [[ -f "$f" ]] || continue
 cp -a "$f" "$BACKUP/$(echo "$f"|sed 's#[/ ]#_#g')"
done

echo "============================================================"
echo " HYPER-HOST SQL ADMIN MANAGER v1"
echo " Server: #$SID"
echo " Backup: $BACKUP"
echo "============================================================"

PATCHER="$(mktemp)"
trap 'rm -f "$PATCHER"' EXIT
base64 -d >"$PATCHER" <<'PATCHER_B64'

PATCHER_B64

echo "[1/6] Patching backend + panel..."
python3 "$PATCHER" "$SRC_CTL" "$LIVE_CTL" "$SRC_UI" "$LIVE_UI"

echo "[2/6] Syntax checks..."
python3 -m py_compile "$SRC_CTL"
python3 -m py_compile "$LIVE_CTL"
php -l "$SRC_UI" >/dev/null
php -l "$LIVE_UI" >/dev/null

echo "[3/6] Installing live controller..."
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
chown www-data:www-data "$LIVE_UI" 2>/dev/null || true
chmod 0644 "$LIVE_UI"

echo "[4/6] Verifying commands..."
"$LIVE_CTL" --help 2>&1 | grep -q sql-admins-list
"$LIVE_CTL" --help 2>&1 | grep -q sql-admin-grant
"$LIVE_CTL" --help 2>&1 | grep -q sql-admin-delete

echo "[5/6] Checking SQL Admin Loader bridge..."
set +e
"$LIVE_CTL" sql-admins-list "$SID"
RC=$?
set -e
if [[ $RC -ne 0 ]]; then
 echo "[ERROR] SQL Admin Manager installed, but Admin Loader SQL bridge is not ready for server #$SID."
 exit $RC
fi

echo "[6/6] Reloading PHP-FPM..."
while read -r svc; do
 [[ -n "$svc" ]] || continue
 systemctl reload "$svc" 2>/dev/null || true
done < <(systemctl list-units --type=service --state=running --no-legend | awk '/php.*fpm/ {print $1}')

echo
echo "[SUCCESS] SQL ADMIN MANAGER v1 INSTALLED"
echo "Open: Server -> Админки"
echo "Direct SQL: *_amxadmins + *_admins_servers"
echo "Supports: SteamID / nick / IP, days / months / forever"
echo "Backup: $BACKUP"
